export type RegelId = keyof typeof KATALOG
type Kat = typeof KATALOG
/** Regeln mit eigenem Befund (befund und weiche) im Entscheidbaum: für sie muss regeln.ts eine Funktion liefern (ohne Grundprüfung B5) */
export type BefundId = { [K in RegelId]: Kat[K]['gruppe'] extends 'B5' ? never : Kat[K]['art'] extends 'befund' | 'weiche' ? K : never }[RegelId]
/** Regeln der Grundprüfung (Gruppe B5): für sie muss grundpruefung.ts eine Funktion liefern */
export type GrundId = { [K in RegelId]: Kat[K]['gruppe'] extends 'B5' ? K : never }[RegelId]
export const REGEL_IDS = Object.keys(KATALOG) as RegelId[]
export const regelDef = (id: RegelId): RegelDef => KATALOG[id]

/** Quellen einer Regel als Kurztext mit Ausgabe, z. B. «VSS 40 241:2019-03 Z. 24; VSS 40 240:2025-07 Z. 10» */
export function quellText(id: RegelId): string {
  return regelDef(id).quellen.map(x => {
    const w = WERKE[x.werk as WerkId]
    return `${w.name}:${w.ausgabe} ${x.ziffer}`
  }).join('; ')
}
